content.text:
{
  "name": "自动微孔板培养箱",
  "name_en": "Automated microplate incubator",
  "manufacturer": "",
  "description": "一种用于存放并温控培养微孔板或培养板的自动化实验室培养箱，通常具有多个板位、装载托盘和可开闭门机构，可在设定温度下进行样品孵育，并支持板件取放与振荡混匀。常用于细胞培养、酶反应、样品保温和自动化流程中的板式孵育步骤。",
  "description_en": "An automated laboratory incubator for storing and temperature-controlling microplates or assay plates. It typically provides multiple plate sites, a loading tray, and a door mechanism, allowing incubation at a set temperature as well as automated plate transfer and shaking. It is commonly used for cell culture, enzyme reactions, sample holding, and plate incubation steps in lab automation workflows.",
  "tag_hints": [
    "microplate incubation",
    "automated plate handling",
    "temperature control",
    "plate storage",
    "loading tray",
    "plate shaking",
    "lab automation"
  ],
  "actions": [
    {
      "action_name": "auto-racks",
      "description": "列出培养箱内的板架或板位信息",
      "description_en": "List rack or plate-site information in the incubator"
    },
    {
      "action_name": "auto-get_num_free_sites",
      "description": "获取空闲板位数量",
      "description_en": "Get the number of free plate sites"
    },
    {
      "action_name": "auto-get_site_by_plate_name",
      "description": "根据板名查找所在板位",
      "description_en": "Find the site holding a plate by its name"
    },
    {
      "action_name": "auto-fetch_plate_to_loading_tray",
      "description": "将指定培养板从培养箱取到装载托盘",
      "description_en": "Fetch a specified plate from the incubator to the loading tray"
    },
    {
      "action_name": "auto-find_smallest_site_for_plate",
      "description": "查找可容纳该培养板的最小合适板位",
      "description_en": "Find the smallest suitable site for a plate"
    },
    {
      "action_name": "auto-find_random_site",
      "description": "随机查找一个可用板位",
      "description_en": "Find a random available site"
    },
    {
      "action_name": "auto-take_in_plate",
      "description": "将装载托盘上的培养板放入培养箱指定板位",
      "description_en": "Take a plate from the loading tray into a specified incubator site"
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置培养箱温度",
      "description_en": "Set the incubator temperature"
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取培养箱温度",
      "description_en": "Get the incubator temperature"
    },
    {
      "action_name": "auto-open_door",
      "description": "打开培养箱门",
      "description_en": "Open the incubator door"
    },
    {
      "action_name": "auto-close_door",
      "description": "关闭培养箱门",
      "description_en": "Close the incubator door"
    },
    {
      "action_name": "auto-start_shaking",
      "description": "以设定频率开始振荡",
      "description_en": "Start shaking at the specified frequency"
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡",
      "description_en": "Stop shaking"
    },
    {
      "action_name": "auto-summary",
      "description": "汇总培养箱当前状态与板位占用情况",
      "description_en": "Summarize the current incubator status and site occupancy"
    },
    {
      "action_name": "auto-serialize",
      "description": "导出培养箱配置或当前布局信息",
      "description_en": "Export incubator configuration or current layout information"
    },
    {
      "action_name": "auto-deserialize",
      "description": "从已保存数据恢复培养箱配置或布局",
      "description_en": "Restore incubator configuration or layout from saved data"
    }
  ]
}

